export function getProductBySlug(slug) {
  if (!slug) return null;
  const decoded = decodeURIComponent(slug).toLowerCase().trim();
  const normalized = decoded.replace(/--+/g, '-').replace(/^-+|-+$/g, '');
  const compact = normalized.replace(/[^a-z0-9]/g, '');

  return productsData.find(p => {
    if (p.slug === decoded || p.slug === normalized) return true;
    if (p.id === decoded || p.id === normalized) return true;
    if (p.name.toLowerCase() === decoded || p.name.toLowerCase() === normalized) return true;
    if (p.name.toLowerCase().replace(/\s+/g, '-') === normalized) return true;
    if (p.slug.replace(/[^a-z0-9]/g, '') === compact) return true;
    return false;
  }) || null;
}

export function getProductsByCategory(catSlug) {
  if (!catSlug || catSlug === 'all') return productsData;
  const clean = catSlug.toLowerCase().trim();
  return productsData.filter(p => p.category === clean || p.category.replace(/-/g, '') === clean.replace(/-/g, ''));
}

